  Local Notation shobj_val := (@LbA_DCtorK.shobj_val ra sp gp tp s0 s1 a0 a1 a2 a3 a4 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ds ppos pcons pstr pstr2 err pos Ha0 Ha2 Ha3 Ha5 Herr DSO PPL S1O S2O PCO) (only parsing).
  Local Notation shz_ok := (@LbA_DCtorK.shz_ok ra sp gp tp s0 s1 a0 a1 a2 a3 a4 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ds ppos pcons pstr pstr2 err lo pos j1 j2 Ha0 Ha2 Ha3 Ha5 Herr DSO PPL S1O S2O PCO) (only parsing).
