  Local Notation shdj_ok := (@LbA_DCtorK.shdj_ok HCEIL ra sp gp tp s0 s1 a0 a1 a2 a3 a4 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 ds ppos pcons pstr pstr2 err lo pos Ha0 Ha2 Ha3 Ha5 Herr DSO PPL S1O S2O PCO STK CEIL LO SPHI) (only parsing).
  Local Notation kshd_ok := (@LbA_DCtorK.kshd_ok HCEIL ra sp gp tp s0 s1 a0 a1 a2 a3 a4 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 ds ppos pcons pstr pstr2 err lo pos Ha0 Ha2 Ha3 Ha5 Herr DSO PPL S1O S2O PCO STK CEIL LO SPHI) (only parsing).
  Local Notation kst_ok := (@LbA_DCtorK.kst_ok HCEIL ra sp gp tp s0 s1 a0 a1 a2 a3 a4 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 ds ppos pcons pstr pstr2 err lo pos j1 j2 Ha0 Ha2 Ha3 Ha5 Herr DSO PPO PPL S1O S2O PCO DISJ STK CEIL LO SPHI SPOBJ) (only parsing).
  Local Notation HB1c := (@LbA_DCtorK.HB1c ra sp gp tp s0 s1 a0 a1 a2 a3 a4 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11) (only parsing).
  Local Notation HB2c := (@LbA_DCtorK.HB2c ra sp gp tp s0 s1 a0 a1 a2 a3 a4 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ds ppos pcons pstr pstr2 err pos Ha0 DSO PPL) (only parsing).
  Local Notation HW1c := (@LbA_DCtorK.HW1c HCEIL sp m0 ds ppos pcons pstr pstr2 err lo pos PPL STK CEIL LO SPHI) (only parsing).
